package com.cxy.workbench;
import android.animation.ValueAnimator;
import android.content.Context;
import android.graphics.*;
import android.graphics.drawable.Drawable;
import android.os.Bundle;
import android.view.*;
import android.view.accessibility.*;
import org.json.*;
import java.util.*;

/** A gateway-centred device map. Link colours require the existing observed network evidence. */
final class DeviceOrbit extends android.widget.FrameLayout {
 interface Listener {void select(String id);}
 static final String[] IDS={"gateway","mac","winpc","linux","phone"};
 final Listener listener;final Paint p=new Paint(3);final float[] xs=new float[5],ys=new float[5],radii=new float[5],drawn=new float[5],targets=new float[5];final int[] colors={0xff20a887,0xff3482ff,0xff8a6bda,0xff1fa7a0,0xffd58a28};
 JSONObject snapshot;String focused="overview";float focus;int pressed=-1,accessFocus=-1;float downX,downY;ValueAnimator focusAnimator,valueAnimator;final DashPathEffect dash;final android.widget.ImageButton[] buttons=new android.widget.ImageButton[5];
 DeviceOrbit(Context c,Listener l){super(c);listener=l;Arrays.fill(targets,Float.NaN);dash=new DashPathEffect(new float[]{dp(3),dp(5)},0);setWillNotDraw(false);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);for(int n=0;n<5;n++){final int index=n;android.widget.ImageButton b=new android.widget.ImageButton(c);b.setBackground(HyperStyle.press(c,Color.TRANSPARENT,100));b.setContentDescription(title(n));b.setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_YES);b.setOnClickListener(v->listener.select(IDS[index]));buttons[n]=b;addView(b,new android.widget.FrameLayout.LayoutParams(1,1));}}
 float dp(float n){return n*getResources().getDisplayMetrics().density;}
 JSONObject sample(int n){return n==0?snapshot==null?null:snapshot.optJSONObject("gateway"):DeviceText.sample(snapshot,IDS[n]);}
 String title(int n){return n==0?"网关":DeviceText.title(IDS[n]);}
 boolean fresh(int n){return n==0?WidgetNetwork.privateConnected(WidgetNetwork.privateLabel(sample(n),System.currentTimeMillis())):DeviceText.hardwareFresh(sample(n),System.currentTimeMillis());}
 float value(int n){if(n==0)return fresh(0)?100:Float.NaN;JSONObject d=sample(n);double value=DeviceText.number(d,n==4?"batteryPercent":"cpu");return Double.isNaN(value)?Float.NaN:(float)Math.max(0,Math.min(100,value));}
 void update(JSONObject data){snapshot=data;float[] start=drawn.clone(),next=new float[5];boolean changed=false;for(int n=0;n<5;n++){next[n]=value(n);if(Float.compare(next[n],targets[n])!=0)changed=true;}System.arraycopy(next,0,targets,0,5);if(changed){if(valueAnimator!=null)valueAnimator.cancel();if(HyperStyle.motion()){valueAnimator=ValueAnimator.ofFloat(0,1);valueAnimator.setDuration(240);valueAnimator.addUpdateListener(a->{float t=(float)a.getAnimatedValue();for(int n=0;n<5;n++)drawn[n]=Float.isNaN(targets[n])?0:start[n]+(targets[n]-start[n])*t;invalidate();});valueAnimator.start();}else for(int n=0;n<5;n++)drawn[n]=Float.isNaN(targets[n])?0:targets[n];}invalidate();}
 void focus(String id){if(focusAnimator!=null)focusAnimator.cancel();if(!id.equals("overview")&&!id.equals(focused))focus=0;if(!id.equals("overview"))focused=id;float end=id.equals("overview")?0:1;if(HyperStyle.motion()){focusAnimator=ValueAnimator.ofFloat(focus,end);focusAnimator.setDuration(280);focusAnimator.setInterpolator(new android.view.animation.DecelerateInterpolator());focusAnimator.addUpdateListener(a->{focus=(float)a.getAnimatedValue();resize();});focusAnimator.addListener(new android.animation.AnimatorListenerAdapter(){@Override public void onAnimationEnd(android.animation.Animator animation){if(end==0){focused="overview";invalidate();}}});focusAnimator.start();}else{focus=end;if(end==0)focused="overview";resize();}int chosen=selected();if(chosen>=0)buttons[chosen].bringToFront();sendAccessibilityEvent(AccessibilityEvent.TYPE_WINDOW_CONTENT_CHANGED);}
 void resize(){ViewGroup.LayoutParams lp=getLayoutParams();if(lp!=null){int height=(int)dp(310-140*focus);if(lp.height!=height){lp.height=height;setLayoutParams(lp);}}requestLayout();invalidate();}
 int selected(){for(int n=0;n<5;n++)if(IDS[n].equals(focused))return n;return -1;}
 void geometry(){float w=getWidth(),h=getHeight(),cx=w/2,cy=h/2;xs[0]=cx;ys[0]=cy;radii[0]=dp(47);float[] fx={0,.23f,.77f,.23f,.77f},fy={0,.18f,.18f,.76f,.76f};int selected=selected();for(int n=1;n<5;n++){xs[n]=w*fx[n];ys[n]=h*fy[n];radii[n]=dp(36);}if(selected>=0){for(int n=0;n<5;n++)if(n==selected){xs[n]+=(cx-xs[n])*focus;ys[n]+=(cy-ys[n])*focus;radii[n]+=(dp(61)-radii[n])*focus;}else{radii[n]*=1-.28f*focus;if(n==0){xs[n]+=(w*.095f-xs[n])*focus;}else xs[n]+=(n==1||n==3?-dp(8):dp(8))*focus;}}if(pressed>=0)radii[pressed]*=.96f;}
 @Override protected void onDraw(Canvas c){super.onDraw(c);geometry();int chosen=selected();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1.5f));p.setPathEffect(dash);for(int n=1;n<5;n++){String state=WidgetNetwork.privateLabel(sample(n),System.currentTimeMillis());p.setColor(WidgetNetwork.privateConnected(state)?0xff20a887:HyperStyle.muted(getContext()));p.setAlpha((int)(focus>0?65:105));c.drawLine(xs[0],ys[0],xs[n],ys[n],p);}p.setPathEffect(null);p.setAlpha(255);for(int n=0;n<5;n++)if(n!=chosen)node(c,n,1-.65f*focus);if(chosen>=0)node(c,chosen,1);}
 void text(Canvas c,String text,float x,float baseline,float size,int color,boolean bold,float alpha){p.setStyle(Paint.Style.FILL);p.setColor(color);p.setAlpha((int)(255*alpha));p.setTextAlign(Paint.Align.CENTER);p.setTextSize(dp(size));p.setTypeface(bold?Typeface.create("sans-serif-medium",0):Typeface.DEFAULT);c.drawText(text,x,baseline,p);p.setAlpha(255);}
 void node(Canvas c,int n,float alpha){float x=xs[n],y=ys[n],r=radii[n];boolean chosen=n==selected()&&focus>0;int tint=fresh(n)?colors[n]:HyperStyle.muted(getContext());p.setStyle(Paint.Style.FILL);p.setColor(HyperStyle.surface(getContext()));p.setAlpha((int)(255*alpha));c.drawCircle(x,y,r+dp(5),p);p.setColor(colors[n]);p.setAlpha((int)((chosen?25:12)*alpha));c.drawCircle(x,y,r-dp(3),p);p.setAlpha((int)(255*alpha));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(chosen?6:4));p.setStrokeCap(Paint.Cap.ROUND);p.setColor(HyperStyle.soft(getContext()));c.drawCircle(x,y,r,p);if(!Float.isNaN(targets[n])){p.setColor(tint);p.setAlpha((int)(255*alpha));c.drawArc(x-r,y-r,x+r,y+r,-90,Math.min(360,drawn[n]*3.6f),false,p);}p.setAlpha(255);
  float iconSize=chosen?24:18;Drawable icon=HyperStyle.icon(getContext(),IDS[n],tint);int size=(int)dp(iconSize);icon.setBounds((int)x-size/2,(int)(y-dp(chosen?34:24)),(int)x+size/2,(int)(y-dp(chosen?34:24))+size);icon.setAlpha((int)(255*alpha));icon.draw(c);
  String number=n==0?(fresh(0)?"在线":"未知"):CardMetrics.percent(targets[n]);text(c,number,x,y+dp(chosen?10:9),chosen?26:18,HyperStyle.ink(getContext()),true,alpha);if(n>0)text(c,n==4?"电量":"CPU",x,y+dp(chosen?33:25),chosen?13:10,HyperStyle.muted(getContext()),false,alpha);text(c,title(n),x,y+r+dp(22),chosen?17:14,HyperStyle.ink(getContext()),chosen,alpha*(1-focus));
 }
 int hit(float x,float y){int chosen=selected();if(chosen>=0&&Math.hypot(x-xs[chosen],y-ys[chosen])<radii[chosen]+dp(10))return chosen;for(int n=0;n<5;n++)if(Math.hypot(x-xs[n],y-ys[n])<radii[n]+dp(10))return n;return -1;}
 @Override public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){pressed=hit(e.getX(),e.getY());downX=e.getX();downY=e.getY();invalidate();return pressed>=0;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){if(Math.hypot(e.getX()-downX,e.getY()-downY)>ViewConfiguration.get(getContext()).getScaledTouchSlop()){pressed=-1;invalidate();}return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){int n=pressed;pressed=-1;invalidate();if(n>=0){performClick();listener.select(IDS[n]);}return true;}if(e.getActionMasked()==MotionEvent.ACTION_CANCEL){pressed=-1;invalidate();return true;}return super.onTouchEvent(e);}
 @Override public boolean performClick(){super.performClick();return true;}
 @Override protected void onLayout(boolean changed,int left,int top,int right,int bottom){geometry();for(int n=0;n<5;n++){int r=(int)(radii[n]+dp(7));buttons[n].layout((int)xs[n]-r,(int)ys[n]-r,(int)xs[n]+r,(int)ys[n]+r);}}
 @Override protected void onDetachedFromWindow(){if(focusAnimator!=null)focusAnimator.cancel();if(valueAnimator!=null)valueAnimator.cancel();super.onDetachedFromWindow();}
}
